import json
import re
import urllib.request
from urllib.error import HTTPError, URLError
from pathlib import Path

npm_audit_path = Path('/root/npm-audit.json')
lock_path = Path('/root/package-lock.json')

with npm_audit_path.open('r', encoding='utf-8') as f:
    audit = json.load(f)

with lock_path.open('r', encoding='utf-8') as f:
    lock = json.load(f)

packages = lock.get('packages', {})
# Map node path -> version
node_version = {}
for path, info in packages.items():
    if not path or path == "":
        continue
    ver = info.get('version')
    if ver:
        node_version[path] = ver

# OSV cache
osv_cache = {}

def fetch_osv(ghsa_id):
    if ghsa_id in osv_cache:
        return osv_cache[ghsa_id]
    url = f"https://api.osv.dev/v1/vulns/{ghsa_id}"
    try:
        with urllib.request.urlopen(url, timeout=20) as resp:
            data = json.load(resp)
            osv_cache[ghsa_id] = data
            return data
    except (HTTPError, URLError, json.JSONDecodeError):
        osv_cache[ghsa_id] = None
        return None


def pick_cve_from_osv(osv):
    if not osv:
        return None
    for alias in osv.get('aliases', []) or []:
        if alias.startswith('CVE-'):
            return alias
    return None


def pick_cvss_from_osv(osv):
    if not osv:
        return None
    # OSV severity list may contain CVSS scores
    for sev in osv.get('severity', []) or []:
        if sev.get('type', '').startswith('CVSS') and sev.get('score'):
            return sev.get('score')
    return None

rows = []
seen = set()

ghsa_re = re.compile(r"GHSA-[0-9a-z]{4}-[0-9a-z]{4}-[0-9a-z]{4}", re.I)

for pkg_name, v in audit.get('vulnerabilities', {}).items():
    via = v.get('via', [])
    nodes = v.get('nodes', [])
    fix_avail = v.get('fixAvailable')
    fixed_version = "N/A"
    if isinstance(fix_avail, dict):
        fixed_version = fix_avail.get('version') or "N/A"
    # Only process actual advisories
    for adv in via:
        if not isinstance(adv, dict):
            continue
        severity = (adv.get('severity') or '').lower()
        if severity not in ('high', 'critical'):
            continue
        url = adv.get('url') or ""
        title = adv.get('title') or ""
        cvss_score = None
        cvss_obj = adv.get('cvss') or {}
        if isinstance(cvss_obj, dict):
            cvss_score = cvss_obj.get('score')
        cve_id = None
        ghsa_id = None
        m = ghsa_re.search(url)
        if m:
            ghsa_id = m.group(0).upper()
            osv = fetch_osv(ghsa_id)
            cve_id = pick_cve_from_osv(osv)
            if not cvss_score or cvss_score == 0:
                cvss_score = pick_cvss_from_osv(osv)
        if not cve_id:
            cve_id = "N/A"
        if cvss_score is None:
            cvss_score = "N/A"
        # Map versions from nodes; if none, leave N/A
        if nodes:
            for node in nodes:
                ver = node_version.get(node, "N/A")
                key = (pkg_name, ver, url, cve_id)
                if key in seen:
                    continue
                seen.add(key)
                rows.append({
                    "Package": pkg_name,
                    "Version": ver,
                    "CVE_ID": cve_id,
                    "Severity": severity.upper(),
                    "CVSS_Score": cvss_score,
                    "Fixed_Version": fixed_version,
                    "Title": title,
                    "Url": url,
                })
        else:
            key = (pkg_name, "N/A", url, cve_id)
            if key in seen:
                continue
            seen.add(key)
            rows.append({
                "Package": pkg_name,
                "Version": "N/A",
                "CVE_ID": cve_id,
                "Severity": severity.upper(),
                "CVSS_Score": cvss_score,
                "Fixed_Version": fixed_version,
                "Title": title,
                "Url": url,
            })

# Sort rows for stable output
rows.sort(key=lambda r: (r["Severity"], r["Package"], str(r["Version"])) )

out_path = Path('/root/security_audit.csv')
import csv
with out_path.open('w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=[
        "Package","Version","CVE_ID","Severity","CVSS_Score","Fixed_Version","Title","Url"
    ])
    writer.writeheader()
    writer.writerows(rows)

print(f"Wrote {len(rows)} rows to {out_path}")
